const repo = ($env.GITHUB_REPO || '').trim();
const [owner, name] = repo.split('/');
if (!owner || !name || repo.split('/').length !== 2) {
  throw new Error('GITHUB_REPO must be owner/repository');
}
for (const key of ['GITHUB_TOKEN', 'ANTHROPIC_API_KEY', 'DISCORD_WEBHOOK_URL']) {
  if (!$env[key]) throw new Error(`${key} is not configured`);
}
const until = new Date();
const since = new Date(until.getTime() - 7 * 24 * 60 * 60 * 1000);
return [{ json: { owner, name, repo, since: since.toISOString(), until: until.toISOString(), language: ($env.SUMMARY_LANG || 'EN').toUpperCase() } }];

const result = $json.data?.repository;
if (!$json.data || $json.errors?.length || !result) {
  throw new Error(`GitHub API failed: ${JSON.stringify($json.errors || $json)}`);
}
const commits = result.commits?.history?.nodes || [];
const issues = result.issues?.nodes || [];
const pullRequests = result.pullRequests?.nodes || [];
const input = $('Prepare configuration').first().json;
const prompt = `Write a weekly engineering summary for ${input.repo}. Use ${input.language === 'FR' ? 'French' : 'English'}.

Period: ${input.since} through ${input.until}

Commits (${commits.length}):
${JSON.stringify(commits)}

Closed issues (${issues.length}):
${JSON.stringify(issues)}

Merged pull requests (${pullRequests.length}):
${JSON.stringify(pullRequests)}

Return Markdown with: a 2-3 sentence overview, shipped changes, fixes, notable risks or follow-ups, and a short activity count. Do not invent details not present in the data.`;
return [{ json: { ...input, prompt, counts: { commits: commits.length, issues: issues.length, pullRequests: pullRequests.length } } }];

const summary = $json.content?.find(part => part.type === 'text')?.text;
if (!summary) throw new Error(`Claude API returned no text: ${JSON.stringify($json)}`);
return [{ json: { content: `**${$('Prepare configuration').first().json.repo} weekly summary**\n\n${summary}` } }];
